from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from constance import config

class DynamicOAuthCredentialsView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request, provider, app_id):
        if not request.user.registered_oauth_apps.filter(app_id=app_id, provider=provider.lower()).exists():
            return Response({"error": "Access denied to requested application credentials"}, status=403)

        client_secret = getattr(config, f"OAUTH_{provider.upper()}_SECRET_{app_id}", None)
        redirect_uri = getattr(config, f"OAUTH_{provider.upper()}_REDIRECT_{app_id}", None)

        if not client_secret:
            return Response({"error": "OAuth application credentials not found"}, status=404)

        return Response({
            "provider": provider,
            "app_id": app_id,
            "client_secret": client_secret,
            "redirect_uri": redirect_uri
        })
